// Swaps a todo's text for a field. Enter or blur saves; Escape discards.
// An empty edit keeps the old text rather than deleting the todo.
function startEdit(text, todo) {
  var field = document.createElement('input');
  field.type = 'text';
  field.className = 'edit';
  field.setAttribute('data-testid', 'todo-edit');
  field.setAttribute('aria-label', 'Edit "' + todo.text + '"');
  field.value = todo.text;
  var finished = false;

  function finish(commit) {
    if (finished) return;
    finished = true;
    var value = field.value.trim();
    if (commit && value && value !== todo.text) {
      todos = todos.map(function (t) {
        return t.id === todo.id ? Object.assign({}, t, { text: value }) : t;
      });
      save(todos);
    }
    render();
  }

  field.addEventListener('keydown', function (event) {
    if (event.isComposing) return;
    if (event.key === 'Enter') { event.preventDefault(); finish(true); }
    else if (event.key === 'Escape') { event.preventDefault(); finish(false); }
  });
  field.addEventListener('blur', function () { finish(true); });

  text.replaceWith(field);
  field.focus();
  field.select();
}

